<?php
require_once __DIR__.'/includes/auth.php';
if(currentUser()) redirect(url('admin/dashboard.php'));
$errors=[];
if(isPost()){ verifyCsrf(); $email=mb_strtolower(trim($_POST['email']??'')); $password=(string)($_POST['password']??''); if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$password==='')$errors[]='أدخل بريدًا إلكترونيًا وكلمة مرور صحيحين.'; if(!$errors){$s=db()->prepare('SELECT id,password,status FROM users WHERE email=? LIMIT 1');$s->execute([$email]);$u=$s->fetch();if($u&&$u['status']==='active'&&password_verify($password,$u['password'])){loginUser((int)$u['id']);redirect(url('admin/dashboard.php'));}$errors[]='بيانات الدخول غير صحيحة أو الحساب معطّل.';}}
$pageTitle='تسجيل الدخول'; require __DIR__.'/includes/header.php'; ?>
<div class="container auth-shell py-5"><div class="auth-card"><div class="text-center mb-4"><i class="bi bi-shield-lock display-4 text-danger"></i><h1 class="h3 fw-bold mt-2">تسجيل الدخول</h1><p class="text-secondary">مرحبًا بعودتك إلى غرفة الأخبار</p></div><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><form method="post"><?=csrfField()?><div class="mb-3"><label class="form-label">البريد الإلكتروني</label><input class="form-control form-control-lg" type="email" name="email" required autofocus value="<?=e($_POST['email']??'')?>"></div><div class="mb-4"><label class="form-label">كلمة المرور</label><input class="form-control form-control-lg" type="password" name="password" required></div><button class="btn btn-primary btn-lg w-100">دخول</button></form><?php if(setting('allow_registration','0')==='1'):?><p class="text-center mt-4 mb-0">ليس لديك حساب؟ <a href="<?=url('register.php')?>">إنشاء حساب</a></p><?php endif;?></div></div>
